(function(g){'use strict';g.AgendappxSocial={crear(ctx){
 const {Store,list,openSheet,closeSheet,navSheet,toast,esc,money}=ctx,$=(s,r=document)=>r.querySelector(s);let dato=null;
 async function api(ruta='',d,metodo=d===undefined?'GET':'POST'){const s=await g.AgendappxCuentas.sesion();if(!s||s.sinConexion)throw new Error('Entra con tu cuenta y conéctate a internet.');const r=await fetch('/api/negocios/'+s.negocioId+'/social'+ruta,{method:metodo,headers:{'Content-Type':'application/json',Authorization:'Bearer '+s.accessToken},...(d===undefined?{}:{body:JSON.stringify(d)}),cache:'no-store',signal:AbortSignal.timeout(15000)});const datos=await r.json();const actual=await g.AgendappxCuentas.sesion();if(!actual||actual.negocioId!==s.negocioId||actual.usuarioId!==s.usuarioId)throw new Error('Tu cuenta cambió. Abre de nuevo esta pantalla.');if(!r.ok)throw new Error(datos.error||'No se pudo guardar.');return datos;}
 function hoja(t,h,fn){openSheet(navSheet(t,'Listo')+h,t,r=>{r.addEventListener('click',e=>{if(e.target.closest('[data-close],[data-done]'))closeSheet();});fn?.(r);});}
 const celda=(t,h)=>`<label class="cell"><span class="l">${t}</span>${h}</label>`;
 async function comprimir(file){if(!file||!file.type.startsWith('image/'))throw new Error('Elige una foto de tu cámara o galería.');if(file.size>20*1024*1024)throw new Error('La foto supera 20 MB.');const bitmap=await createImageBitmap(file),c=document.createElement('canvas'),escala=Math.min(1,900/Math.max(bitmap.width,bitmap.height));c.width=Math.max(1,Math.round(bitmap.width*escala));c.height=Math.max(1,Math.round(bitmap.height*escala));c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();let calidad=.82,foto=c.toDataURL('image/jpeg',calidad);while(foto.length>48000&&calidad>.2){calidad-=.08;foto=c.toDataURL('image/jpeg',calidad);}if(foto.length>48000){const peque=document.createElement('canvas');peque.width=Math.round(c.width*.6);peque.height=Math.round(c.height*.6);peque.getContext('2d').drawImage(c,0,0,peque.width,peque.height);foto=peque.toDataURL('image/jpeg',.5);}if(foto.length>48000)throw new Error('La foto tiene demasiado detalle. Recórtala e intenta otra vez.');return foto;}
 async function cargar(t){hoja(t,'<p class="foot" id="social-carga" role="status">Consultando tu salón…</p>');const root=$('#sheetCard');try{const d=await api();if(!root.isConnected||!$('#social-carga',root))return null;dato=d;return {d,root};}catch(e){if($('#social-carga',root))$('#social-carga',root).textContent=e.message;return null;}}
 async function perfilNegocio(){const cargado=await cargar('Perfil público');if(!cargado)return;const {d,root}=cargado,p=d.perfil;
 if(!p){$('#social-carga',root).textContent='Solo Admin puede editar el perfil. Abre Modo cliente para consultar el directorio.';return;}
 root.innerHTML='<div class="grab"></div>'+navSheet('Perfil público','')+`<form id="perfil-publico-form"><p class="foot">Solo lo que actives aquí se muestra a clientas. Las citas y teléfonos permanecen privados.</p><div class="group">${celda('Mostrar mi salón en Agendappx',`<button class="sw" type="button" id="perfil-visible" role="switch" aria-label="Mostrar mi salón" aria-checked="${p.visible}"></button>`)}${celda('Enlace',`<input id="perfil-slug" class="in" required pattern="[a-z0-9][a-z0-9-]{2,59}" placeholder="ab-beauty-room" maxlength="60" value="${esc(p.slug||'')}">`)}${celda('Ciudad',`<input id="perfil-ciudad" class="in" maxlength="100" value="${esc(p.ciudad)}">`)}${celda('Colonia',`<input id="perfil-colonia" class="in" maxlength="150" value="${esc(p.colonia)}">`)}${celda('Dirección del salón',`<input id="perfil-direccion" class="in" maxlength="300" value="${esc(p.direccion)}">`)}${celda('WhatsApp público',`<input id="perfil-whatsapp" class="in" inputmode="tel" maxlength="24" placeholder="Opcional" value="${esc(p.whatsapp||'')}">`)}</div><div class="group"><label class="cell" style="display:block">Descripción<textarea class="in" id="perfil-descripcion" maxlength="1000" style="width:100%;min-height:100px">${esc(p.descripcion)}</textarea></label>${celda('Logo',`<input type="file" id="perfil-logo" accept="image/*" style="max-width:60%">`)}${celda('Portada',`<input type="file" id="perfil-portada" accept="image/*" style="max-width:60%">`)}</div><p class="foot">Para aparecer por cercanía puedes añadir la ubicación aproximada del local. No compartas una dirección privada de otra persona.</p><button type="button" class="cell" id="perfil-ubicacion">${p.lat===null?'Usar ubicación del local':'Actualizar ubicación aproximada'}</button><button type="submit" class="btn fill" style="margin:16px;width:calc(100% - 32px)">Guardar perfil</button><p class="foot" id="perfil-error" role="status"></p></form>${p.slug&&p.visible?`<a class="cell" href="/${esc(p.slug)}" target="_blank" rel="noopener">Ver como cliente ↗</a>`:''}<div class="group"><button type="button" class="cell" id="negocio-push">Activar avisos en este dispositivo</button><button type="button" class="cell" id="negocio-no-push">Desactivar avisos</button></div><div id="social-publicadores"></div>`;
 $('#negocio-push',root).onclick=async()=>{try{toast(await g.AgendappxAvisos.activar('negocio'));}catch(e){toast(e.message);}};$('#negocio-no-push',root).onclick=async()=>{try{toast(await g.AgendappxAvisos.desactivar('negocio'));}catch(e){toast(e.message);}};let lat=p.lat,lon=p.lon;$('#perfil-visible',root).onclick=e=>e.currentTarget.setAttribute('aria-checked',String(e.currentTarget.getAttribute('aria-checked')!=='true'));$('#perfil-ubicacion',root).onclick=()=>{if(!navigator.geolocation)return toast('Tu dispositivo no permite obtener ubicación.');navigator.geolocation.getCurrentPosition(v=>{lat=Math.round(v.coords.latitude*1000)/1000;lon=Math.round(v.coords.longitude*1000)/1000;$('#perfil-ubicacion',root).textContent='Ubicación aproximada preparada';},()=>toast('Puedes guardar el perfil sin ubicación.'),{enableHighAccuracy:false,timeout:10000});};
 $('#perfil-publico-form',root).onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const logo=$('#perfil-logo',root).files[0],portada=$('#perfil-portada',root).files[0];await api('/perfil',{slug:$('#perfil-slug',root).value.trim(),descripcion:$('#perfil-descripcion',root).value.trim(),ciudad:$('#perfil-ciudad',root).value.trim(),colonia:$('#perfil-colonia',root).value.trim(),direccion:$('#perfil-direccion',root).value.trim(),whatsapp:$('#perfil-whatsapp',root).value.trim(),visible:$('#perfil-visible',root).getAttribute('aria-checked')==='true',lat,lon,logo:logo?await comprimir(logo):p.logo,portada:portada?await comprimir(portada):p.portada},'PUT');closeSheet();toast('Perfil público guardado.');}catch(e){$('#perfil-error',root).textContent=e.message;}finally{b.disabled=false;}};
 try{const s=await g.AgendappxCuentas.sesion(),r=await fetch('/api/negocios/'+s.negocioId+'/miembros',{headers:{Authorization:'Bearer '+s.accessToken},cache:'no-store',signal:AbortSignal.timeout(10000)});if(!r.ok)return;const equipo=await r.json();if(!$('#social-publicadores',root))return;$('#social-publicadores',root).innerHTML='<p class="gh">Quién puede publicar trabajos</p><div class="group">'+equipo.miembros.filter(m=>m.rol!=='admin').map(m=>`<label class="cell"><span class="l">${esc(m.nombre)}<small>Puede publicar fotos de este salón</small></span><input type="checkbox" data-publicador="${esc(m.id)}" ${d.publicadores.some(x=>x.usuario_id===m.id)?'checked':''}></label>`).join('')+'</div><p class="foot">Admin puede publicar. Quitar acceso al equipo revoca este permiso al momento.</p>';$('#social-publicadores',root).onchange=async e=>{const b=e.target;if(!b.dataset.publicador)return;b.disabled=true;try{await api('/publicadores',{usuarioId:b.dataset.publicador,permitir:b.checked},'PUT');toast('Permiso guardado.');}catch(e){b.checked=!b.checked;toast(e.message);}finally{b.disabled=false;}};}catch{}
 }
 async function publicar(){const cargado=await cargar('Publicar trabajo');if(!cargado)return;const {d,root}=cargado;if(!d.puedePublicar){$('#social-carga',root).textContent='Admin debe darte permiso para publicar trabajos.';return;}const servicios=list('servicio');if(!servicios.length){$('#social-carga',root).textContent='Primero crea un servicio en Servicios y precios.';return;}root.innerHTML='<div class="grab"></div>'+navSheet('Publicar trabajo','')+`<form id="trabajo-form"><div class="group">${celda('Foto',`<button type="button" class="btn" id="trabajo-elegir">Elegir foto</button><input type="file" id="trabajo-foto" accept="image/*" hidden>`)}<label class="cell" style="display:block"><span>¿Qué servicio es?</span><select class="in" id="trabajo-servicio" required style="display:block;width:100%;max-width:none;text-align:left;margin-top:10px">${servicios.map(s=>`<option value="${esc(s.id)}">${esc(s.nombre)} · ${money(s.precio)}</option>`).join('')}</select></label></div><img id="trabajo-previa" hidden alt="Vista previa del trabajo" style="max-height:300px;max-width:100%;margin:auto;border-radius:22px"><label class="cell" style="display:block">Descripción<textarea class="in" id="trabajo-texto" maxlength="1200" style="width:100%;min-height:100px"></textarea></label><label class="cell"><input type="checkbox" id="trabajo-permiso" required><span style="white-space:normal">Tengo permiso para publicar esta foto y el consentimiento de las personas que aparecen.</span></label><p class="foot">La imagen se comprime y se eliminan los datos GPS. Hasta 10 publicaciones al día y 30 fotos por salón. El precio y la duración vienen de tu servicio.</p><p class="foot" id="trabajo-error" role="status"></p><button class="btn fill" type="submit" style="margin:16px;width:calc(100% - 32px)">Publicar</button></form>`;let foto=null;$('#trabajo-elegir',root).onclick=()=>$('#trabajo-foto',root).click();$('#trabajo-foto',root).onchange=async e=>{try{foto=await comprimir(e.target.files[0]);$('#trabajo-previa',root).src=foto;$('#trabajo-previa',root).hidden=false;}catch(e){foto=null;$('#trabajo-error',root).textContent=e.message;}};$('#trabajo-form',root).onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{if(!foto)throw new Error('Elige una foto.');await api('/trabajos',{servicio:$('#trabajo-servicio',root).value,foto,texto:$('#trabajo-texto',root).value.trim(),permiso:$('#trabajo-permiso',root).checked});closeSheet();toast('Trabajo publicado. Activa tu perfil público para que lo vean las clientas.');}catch(e){$('#trabajo-error',root).textContent=e.message;}finally{b.disabled=false;}};}
 async function fotos(){const cargado=await cargar('Fotos de trabajos');if(!cargado)return;const {d,root}=cargado;root.innerHTML='<div class="grab"></div>'+navSheet('Fotos de trabajos','Listo')+`<button type="button" class="cell" id="social-publicar">Publicar un trabajo</button><p class="foot">Fotos publicadas, ligadas a servicios de tu salón.</p><div class="negocio-fotos">${d.trabajos.filter(t=>t.estado!=='retirado').map(t=>`<div><img src="${esc(t.foto)}" alt="${esc(t.texto)}"><p>${esc(t.texto)}</p>${Store.cuenta?.rol==='admin'?`<button type="button" class="btn" data-retirar-trabajo="${t.id}">Retirar foto</button>`:''}</div>`).join('')||'<p class="foot">No hay trabajos publicados todavía.</p>'}</div>${Store.cuenta?.rol==='admin'?'<p class="gh">Comentarios</p><div class="group">'+d.comentarios.map(c=>`<article class="cell" style="display:block"><b>${esc(c.nombre)}</b><p>${esc(c.texto)}</p>${c.estado==='visible'?`<button type="button" data-ocultar-comentario="${c.id}">Ocultar comentario</button>`:'<small>En revisión por reportes</small>'}</article>`).join('')+'</div>':''}`;$('#social-publicar',root).onclick=()=>void publicar();root.addEventListener('click',async e=>{const comentario=e.target.closest('[data-ocultar-comentario]')?.dataset.ocultarComentario;if(comentario){try{await api('/moderar',{tipo:'comentario',id:comentario});await fotos();toast('Comentario oculto.');}catch(e){toast(e.message);}return;}const id=e.target.closest('[data-retirar-trabajo]')?.dataset.retirarTrabajo;if(!id)return;try{await api('/moderar',{tipo:'trabajo',id});await fotos();toast('La foto dejó de ser pública.');}catch(e){toast(e.message);}});}
 async function resenas(){const cargado=await cargar('Reseñas');if(!cargado)return;const {d,root}=cargado;root.innerHTML='<div class="grab"></div>'+navSheet('Reseñas','Listo')+'<p class="foot">Solo reseñas de citas completadas. El salón puede responder; no borrar opiniones.</p><div class="group">'+(d.resenas.map(r=>`<article class="cell" style="display:block"><b style="color:#F5A623">${'★'.repeat(r.estrellas)}</b><small>Cita verificada</small><p>${esc(r.texto)}</p>${r.respuesta?`<p>Tu respuesta: ${esc(r.respuesta)}</p>`:''}${Store.cuenta?.rol==='admin'?`<form data-respuesta="${r.id}"><textarea class="in" maxlength="1500" aria-label="Responder reseña" style="width:100%;min-height:70px">${esc(r.respuesta||'')}</textarea><button class="btn" type="submit">Responder</button></form>`:''}</article>`).join('')||'<p class="foot">Todavía no hay reseñas verificadas.</p>')+'</div>';root.addEventListener('submit',async e=>{const id=e.target.dataset.respuesta;if(!id)return;e.preventDefault();try{await api('/moderar',{tipo:'resena',id,respuesta:e.target.querySelector('textarea').value.trim()});toast('Respuesta guardada.');}catch(e){toast(e.message);}});}
 return {perfilNegocio,publicar,fotos,resenas,api};
}};})(window);
